def rule_fn(row, col):
    import re
    val = row.get(col, "")
    if not isinstance(val, str):
        return False
    s = val
    # multiple spaces between words
    if "  " in s:
        return True
    # period not followed by a space (except if at end of string)
    if re.search(r'\.(?!\s|$)', s):
        return True
    return False

def rule_fn(row, col):
    import re
    val = row.get(col, "")
    if not isinstance(val, str):
        return False
    s = val
    # Flag mojibake and intrusive 'x' noise inside words (letter 'x' between word chars)
    if '\u00ef' in s or '\u00bf' in s or '\u00bd' in s:
        return True
    if re.search(r'(?i)(?<=\w)x(?=\w)', s):
        return True
    return False

def rule_fn(row, col):
    import re
    if col != 'Score':
        return False
    s = str(row.get(col, ""))
    m = re.match(r'^(\d{1,3})%$', s)
    if not m:
        return True
    try:
        v = int(m.group(1))
    except:
        return True
    return v < 0 or v > 100

def rule_fn(row, col):
    import re
    if col != 'ZipCode':
        return False
    s = str(row.get(col, ''))
    return re.match(r'^\d{5}$', s) is None
